-- Boise Cascade, July 2026 — the client's first real month.
--
-- Generated from their own .xlsx by the SAME code the loader runs: rowsToSheet →
-- guessMapping → buildImport. The figures here are therefore the figures the app
-- would have produced from the file, not a second reading of it.
--
-- 397 lines in the sheet became 186 sales rows. 142 subtotal lines were
-- discarded — the report is a pivot with its totals left in, and loading those
-- would have stored the month four times over. 61 lines bought something last
-- year and nothing this period; they cannot be stored, because a zero is not a
-- sale. Their 10,700 in mixed pieces-and-feet is 83,153 LF here, converted
-- through the length carried in each item description, with the original kept in
-- source_quantity beside it.
--
-- NO PRICE ANYWHERE. Boise's report has no value column, so value is null on
-- every row. A dollar figure on any of these would be invention.
--
-- WHAT THIS DOES NOT HAVE is the file itself. The loader puts the original .xlsx
-- in the sell-through bucket and records storage_path; a migration cannot. So
-- storage_path is null and filename records what it came from. When Bianca loads
-- July through the screen, it REPLACES this month and captures the file properly
-- — that is the designed path, and this is a bootstrap so the dashboard is not
-- empty while she gets to it.
--
-- Idempotent: the upload is keyed unique on (org, distributor, period), and the
-- rows hang off it, so re-running changes nothing.

insert into sell_through_uploads
  (org_id, distributor_id, period, uploaded_by, filename, storage_path,
   row_count, unmatched_count)
select
  '11111111-1111-1111-1111-111111111111',
  'd0000000-0000-0000-0000-000000000005',
  '2026-07-01',
  'c0000000-0000-0000-0000-000000000001',
  '55c95fdf23dd4ee39de0a5633439238c.xlsx',
  null,
  186,
  157
where exists (
  select 1 from accounts
   where id = 'd0000000-0000-0000-0000-000000000005'
     and org_id = '11111111-1111-1111-1111-111111111111'
)
on conflict (org_id, distributor_id, period) do nothing;

-- The rows. Branch and dealer are resolved BY NAME rather than by id, so this
-- does not depend on whatever uuid each branch was given when it was created.
-- The dealer join is LEFT: a customer we hold no account for still loads, with
-- the label Boise gave it, which is the whole reason dealer_id is nullable.

insert into sell_through
  (org_id, upload_id, branch_id, dealer_id, dealer_label, period, product,
   quantity, unit, source_quantity, source_unit, value)
