  '11111111-1111-1111-1111-111111111111',
  u.id,
  b.id,
  a.id,
  v.dealer_label,
  '2026-07-01',
  v.product,
  v.quantity,
  'LF',
  v.source_quantity,
  v.source_unit,
  null
